                    hashCode = hashCode * 59 + LOCATION.GetHashCode();
                    if (LOCATION_EXCLUDE != null)
                    hashCode = hashCode * 59 + LOCATION_EXCLUDE.GetHashCode();
                    if (MAXIMUM_AGE != null)
                    hashCode = hashCode * 59 + MAXIMUM_AGE.GetHashCode();
                    if (MINIMUM_AGE != null)
                    hashCode = hashCode * 59 + MINIMUM_AGE.GetHashCode();
                    if (SHOPPING_RETARGETING != null)
                    hashCode = hashCode * 59 + SHOPPING_RETARGETING.GetHashCode();
                    if (TARGETING_STRATEGY != null)
                    hashCode = hashCode * 59 + TARGETING_STRATEGY.GetHashCode();
                return hashCode;
            }
        }

        #region Operators
        #pragma warning disable 1591

        public static bool operator ==(TargetingSpec left, TargetingSpec right)
        {
            return Equals(left, right);
        }

        public static bool operator !=(TargetingSpec left, TargetingSpec right)
        {
            return !Equals(left, right);
        }

        #pragma warning restore 1591
        #endregion Operators
    }
